// ============================================================
//  ЧТО СЧИТАЕМ — отладочный запуск по одной закупке
// ============================================================
//
// На входе ССЫЛКА НА КАРТОЧКУ закупки. Копируется из адресной строки
// браузера, когда закупка открыта на портале.
//
// ПОЧЕМУ НЕ РЕЕСТРОВЫЙ НОМЕР. Портал по номеру не находит ничего —
// проверено 03.10.2026: свежая закупка, только что найденная по слову
// «бумага», по собственному номеру даёт ноль результатов.

return [
  {
    json: {
      закупка: {
        // Ссылка на карточку. Скопировать из браузера.
        ссылка: 'https://zakupki.gov.ru/epz/order/notice/zk20/view/common-info.html?regNumber=0348100051726000071'
      },

      // Чей профиль берём: ключевые слова, экономика, прайс.
      клиент: 'kargin',

      // Куда слать результат и куда — сообщения о сбоях.
      clientChatId: '0000000000',
      ownerChatId: '0000000000',

      // ОТЛАДОЧНОЕ ПЕРЕКРЫТИЕ НАСТРОЕК. Действует только в этом воркфлоу.
      //
      // Присланное в запросе ставится ВЫШЕ файла клиента. В боевом
      // воркфлоу-1 этого нет намеренно; здесь перекрытие оставлено, чтобы
      // пробный запуск стоил дешевле: одна позиция вместо пяти.
      //
      // Стоимость измерена 07.10.2026: одна позиция при двух поисках —
      // около $0,07. Пять позиций, как в боевых настройках, — около $0,34.
      настройки: {
        искатьПоПозициям: 1,

        // Регион, где удобнее искать поставщика. Пусто — по всей стране.
        регионПоставки: ''
      }
    }
  }
];

// Готовим отправку: либо файл со сметой, либо сообщение о сбое.
//
// Файл приходит строкой base64 — n8n не умеет принимать двоичные данные
// внутри JSON, поэтому превращаем их во вложение здесь.

const r = $json;
const настройки = $('Какую закупку считаем').first().json;

if (!r || r.ok !== true) {
  const строки = [
    '🚨 <b>СБОЙ СЕРВИСА</b>',
    '<b>' + ((r && r.сбой) || 'приложение не ответило') + '</b>',
    ''
  ];
  if (r && r.подробно) строки.push(r.подробно);
  if (r && r.номер) строки.push('', 'закупка: ' + r.номер);
  строки.push('', '<i>' + new Date().toISOString() + '</i>');

  return {
    json: {
      естьФайл: false,
      chatId: настройки.ownerChatId,
      text: строки.join('\n')
    }
  };
}

return {
  json: {
    естьФайл: true,
    chatId: настройки.clientChatId,
    // Подпись приходит ГОТОВОЙ и безопасно обрезанной — её собирает
        // приложение (src/notify.js, подписьДляФайла), где это покрыто
        // проверками. Здесь стояло `.slice(0, 1000)`, и 09.10.2026 оно
        // разорвало тег пополам: Telegram отверг сообщение целиком,
        // клиент не получил ни текста, ни файла.
        caption: r.подписьФайла || String(r.подпись || '').slice(0, 900),
    fileName: r.файл.имя,
    позиций: r.позиций,
    сЦеной: r.сЦеной,
    полная: r.полная
  },
  binary: {
    data: {
      data: r.файл.base64,
      mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      fileName: r.файл.имя,
      fileExtension: 'xlsx'
    }
  }
};
